<section class="auth-section auth-centered container"><form class="form-card auth-card" method="post" action="<?= e(url('admin-login')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="admin-login"><div class="eyebrow"><?= t('مساحة فريق حصاد','HASAD TEAM WORKSPACE') ?></div><h1><?= t('دخول الإدارة','Team sign in') ?></h1><p class="caption"><?= t('صفحة خاصة بالإدارة والدعم. المستخدمون يدخلون برقم الموبايل.','For administrators and support. Customers sign in with their phone number.') ?></p><?php field(t('البريد الإلكتروني','Email address'),'email','email','','required maxlength="190" autocomplete="username" dir="ltr"');field(t('كلمة المرور','Password'),'password','password','','required maxlength="512" autocomplete="current-password"'); ?><button class="button button-green button-full"><?= t('دخول مساحة العمل','Open workspace') ?><?= icon('arrow') ?></button><?php if(!ready() || !(int)Db::scalar("SELECT COUNT(*) FROM users WHERE role='super_admin'")): ?><a class="text-link" href="<?= e(url('setup')) ?>"><?= t('إعداد الحساب الأول','Set up the first account') ?></a><?php endif; ?></form></section>
